// SPDX-License-Identifier: Apache-2.0

const SCALE_ROUND = 1e6;

function round6(value) {
  return Math.round(value * SCALE_ROUND) / SCALE_ROUND;
}

function isValidCost(costUsd) {
  return typeof costUsd === 'number' && Number.isFinite(costUsd) && costUsd >= 0;
}

export function summarizeCosts(jobs) {
  if (!Array.isArray(jobs)) throw new TypeError('jobs must be an array');
  let total = 0;
  const agents = {};
  const unknown = [];
  for (const job of jobs) {
    const agent = job.agent;
    if (!agents[agent]) agents[agent] = { jobs: 0, usd: 0 };
    agents[agent].jobs += 1;
    if (isValidCost(job.costUsd)) {
      total += job.costUsd;
      agents[agent].usd += job.costUsd;
    } else {
      unknown.push(job.id);
    }
  }
  const byAgent = {};
  for (const name of Object.keys(agents).sort()) {
    byAgent[name] = { jobs: agents[name].jobs, usd: round6(agents[name].usd) };
  }
  return { totalUsd: round6(total), byAgent, unknown };
}

