import { test } from 'node:test';
import assert from 'node:assert/strict';
import { summarizeCosts } from '../tools/cost-summary.mjs';

test('sums valid costs into totals and per-agent figures', () => {
  const result = summarizeCosts([
    { id: 'a', agent: 'ollama', costUsd: 0.25 },
    { id: 'b', agent: 'claude', costUsd: 1.5 },
    { id: 'c', agent: 'ollama', costUsd: 0.75 },
  ]);
  assert.equal(result.totalUsd, 2.5);
  assert.deepEqual(result.byAgent, {
    claude: { jobs: 1, usd: 1.5 },
    ollama: { jobs: 2, usd: 1 },
  });
  assert.deepEqual(result.unknown, []);
});

test('agent keys are in alphabetical order', () => {
  const result = summarizeCosts([
    { id: '1', agent: 'zeta', costUsd: 1 },
    { id: '2', agent: 'alpha', costUsd: 1 },
    { id: '3', agent: 'mid', costUsd: 1 },
  ]);
  assert.deepEqual(Object.keys(result.byAgent), ['alpha', 'mid', 'zeta']);
});

test('rounds totals and agent usd to 6 decimal places', () => {
  const result = summarizeCosts([
    { id: 'a', agent: 'x', costUsd: 0.1234567 },
    { id: 'b', agent: 'x', costUsd: 0.0000004 },
  ]);
  assert.equal(result.totalUsd, 0.123457);
  assert.equal(result.byAgent.x.usd, 0.123457);
  assert.equal(result.byAgent.x.jobs, 2);
});

test('zero cost is valid and not unknown', () => {
  const result = summarizeCosts([{ id: 'z', agent: 'x', costUsd: 0 }]);
  assert.equal(result.totalUsd, 0);
  assert.deepEqual(result.byAgent, { x: { jobs: 1, usd: 0 } });
  assert.deepEqual(result.unknown, []);
});

test('classifies missing, null, negative, and non-finite costs as unknown in input order', () => {
  const result = summarizeCosts([
    { id: 'm', agent: 'x' },
    { id: 'n', agent: 'x', costUsd: null },
    { id: 'ok', agent: 'x', costUsd: 2 },
    { id: 'neg', agent: 'y', costUsd: -1 },
    { id: 'inf', agent: 'y', costUsd: Infinity },
    { id: 'nan', agent: 'y', costUsd: NaN },
  ]);
  assert.deepEqual(result.unknown, ['m', 'n', 'neg', 'inf', 'nan']);
  assert.equal(result.totalUsd, 2);
  assert.deepEqual(result.byAgent, {
    x: { jobs: 3, usd: 2 },
    y: { jobs: 3, usd: 0 },
  });
});

test('empty input yields zero totals', () => {
  assert.deepEqual(summarizeCosts([]), { totalUsd: 0, byAgent: {}, unknown: [] });
});

test('throws TypeError when jobs is not an array', () => {
  assert.throws(() => summarizeCosts(null), TypeError);
  assert.throws(() => summarizeCosts({}), TypeError);
  assert.throws(() => summarizeCosts('jobs'), TypeError);
});

