// The one place that decides whether a prompt is long and picks its per-token rates.
function ratesFor(price, promptTokens) {
  const long = Boolean(price.longAt && promptTokens > price.longAt);
  return { input: long ? price.longInput : price.input, output: long ? price.longOutput : price.output };
}

// Worst case for one request: every input character counted as a token, plus the full output budget.
export function worstCaseUsd(model, { inputChars, maxTokens }) {
  const price = anthropicPrice(model);
