  });

  test('npm run <name> resolves to the script name', () => {
    assert.equal(npmScriptName(['npm', 'run', 'lint']), 'lint');
    assert.equal(npmScriptName(['npm', 'run', 'build:prod']), 'build:prod');
  });

  test('extra trailing arguments are ignored', () => {
    assert.equal(npmScriptName(['npm', 'run', 'build', '--', '--watch']), 'build');
    assert.equal(npmScriptName(['npm', 'test', '--', '--coverage']), 'test');
  });

  test('an absolute path to npm is matched by basename', () => {
    assert.equal(npmScriptName(['/usr/local/bin/npm', 'run', 'build']), 'build');
    assert.equal(npmScriptName(['/usr/local/bin/npm', 'test']), 'test');
  });

  test('non-npm binaries return null', () => {
    assert.equal(npmScriptName(['npx', 'test']), null);
    assert.equal(npmScriptName(['pnpm', 'run', 'x']), null);
    assert.equal(npmScriptName(['node', 'test']), null);
    assert.equal(npmScriptName(['npm.cmd', 'test']), null);
  });

  test('npm subcommands other than test and run return null', () => {
    assert.equal(npmScriptName(['npm', 'install']), null);
    assert.equal(npmScriptName(['npm', 'ci']), null);
    assert.equal(npmScriptName(['npm', 'exec', 'x']), null);
    assert.equal(npmScriptName(['npm']), null);
  });

  test('test must be the immediate subcommand', () => {
    assert.equal(npmScriptName(['npm', '--silent', 'test']), null);
  });

  test('run without a usable script name returns null', () => {
    assert.equal(npmScriptName(['npm', 'run']), null);
    assert.equal(npmScriptName(['npm', 'run', '']), null);
    assert.equal(npmScriptName(['npm', 'run', undefined]), null);
  });

  test('empty or missing argv returns null', () => {
    assert.equal(npmScriptName([]), null);
    assert.equal(npmScriptName(['']), null);
  });
