describe('scriptIsPlainNode', () => {
  test('a bare node command is plain node', () => {
    assert.equal(scriptIsPlainNode('node'), true);
  });

  test('node followed by arguments is plain node', () => {
    assert.equal(scriptIsPlainNode('node server.js'), true);
    assert.equal(scriptIsPlainNode('node --test tests/'), true);
  });

  test('surrounding whitespace is trimmed before matching', () => {
    assert.equal(scriptIsPlainNode('  node server.js  '), true);
  });

  test('node-prefixed but different programs are not plain node', () => {
    assert.equal(scriptIsPlainNode('nodemon server.js'), false);
    assert.equal(scriptIsPlainNode('node-gyp rebuild'), false);
    assert.equal(scriptIsPlainNode('nodejs server.js'), false);
  });

  test('commands that merely contain node are not plain node', () => {
    assert.equal(scriptIsPlainNode('echo node'), false);
    assert.equal(scriptIsPlainNode('xnode server.js'), false);
    assert.equal(scriptIsPlainNode('npm run node'), false);
  });

  test('matching is case sensitive', () => {
    assert.equal(scriptIsPlainNode('NODE server.js'), false);
    assert.equal(scriptIsPlainNode('Node server.js'), false);
  });

  test('empty and whitespace-only strings are not plain node', () => {
    assert.equal(scriptIsPlainNode(''), false);
    assert.equal(scriptIsPlainNode('   '), false);
  });

  test('non-string inputs are not plain node', () => {
    assert.equal(scriptIsPlainNode(undefined), false);
    assert.equal(scriptIsPlainNode(null), false);
    assert.equal(scriptIsPlainNode(42), false);
    assert.equal(scriptIsPlainNode(['node server.js']), false);
  });
